function SectionIcon({ section }: { section: ActiveSection }) {
  return (
    <span className="rail-icon" aria-hidden="true">
      <AppIcon name={sectionVisual(section).icon} />
    </span>
  );
}

function BrandIcon() {
  return (
    <span className="rail-icon brand" aria-hidden="true">
      <AppIcon name="brand" />
    </span>
  );
}

function PanelTitle({
  title,
  section,
  icon,
}: {
  title: string;
  section?: ActiveSection;
  icon?: IconName;
}) {
  const iconName = icon ?? (section ? sectionVisual(section).icon : "brand");
  return (
    <div
      className="panel-title visual-title"
      style={section ? sectionThemeStyle(section) : brandThemeStyle()}
    >
      <span className="panel-title-icon" aria-hidden="true">
        <AppIcon name={iconName} />
      </span>
      <span>{title}</span>
    </div>
  );
}

function OperationTitle({
  title,
  section,
  icon,
}: {
  title: string;
  section: ActiveSection;
  icon?: IconName;
}) {
  const iconName = icon ?? sectionVisual(section).icon;
  return (
    <div className="operation-title visual-title" style={sectionThemeStyle(section)}>
      <span className="operation-title-icon" aria-hidden="true">
        <AppIcon name={iconName} />
      </span>
      <span>{title}</span>
    </div>
  );
}

function ButtonLabel({ icon, children }: { icon: IconName; children: ReactNode }) {
  return (
    <span className="button-label with-icon">
      <AppIcon name={icon} />
      <span>{children}</span>
    </span>
  );
}

function FieldLabel({
  icon,
  section,
  children,
}: {
  icon: IconName;
  section: ActiveSection;
  children: ReactNode;
}) {
  return (
    <span className="field-label with-icon" style={sectionThemeStyle(section)}>
      <span className="field-label-icon" aria-hidden="true">
        <AppIcon name={icon} />
      </span>
      <span>{children}</span>
    </span>
  );
}

function EmptyNote({
  section,
  icon,
  children,
}: {
  section: ActiveSection;
  icon?: IconName;
  children: ReactNode;
}) {
  const iconName = icon ?? sectionVisual(section).icon;
  return (
    <div className="empty-note with-icon" style={sectionThemeStyle(section)}>
      <span className="empty-note-icon" aria-hidden="true">
        <AppIcon name={iconName} />
      </span>
      <div className="empty-note-copy">{children}</div>
    </div>
  );
}

function ModeNote({
  section,
  icon,
  className,
  children,
}: {
  section: ActiveSection;
  icon?: IconName;
  className?: string;
  children: ReactNode;
}) {
  const iconName = icon ?? sectionVisual(section).icon;
  const classNames = ["mode-note", "with-icon", className].filter(Boolean).join(" ");
  return (
    <div className={classNames} style={sectionThemeStyle(section)}>
      <span className="mode-note-icon" aria-hidden="true">
        <AppIcon name={iconName} />
      </span>
      <div className="mode-note-copy">{children}</div>
    </div>
  );
}

