function FeatureVisual({ section }: { section: ActiveSection }) {
  const visual = sectionVisual(section);
  const mode = featureVisualMode(section);
  return (
    <div
      className={`feature-visual feature-visual-${mode}`}
      style={sectionThemeStyle(section)}
      aria-hidden="true"
    >
      <span className="feature-line main" />
      <span className="feature-line cross" />
      <span className="feature-node primary">
        <AppIcon name={visual.icon} />
      </span>
      <span className="feature-node secondary">
        <AppIcon name={visual.secondaryIcon} />
      </span>
      <span className="feature-node tertiary">
        <AppIcon name={visual.tertiaryIcon} />
      </span>
    </div>
  );
}

function SectionCueMap({ section }: { section: ActiveSection }) {
  const visual = sectionVisual(section);
  const cues = SECTION_CUES[section];
  return (
    <ol
      className="section-cue-map"
      aria-label={`${visual.label} workspace flow`}
    >
      {cues.map((cue, index) => (
        <li
          className={cue.tone ? `section-cue-node ${cue.tone}` : "section-cue-node"}
          key={`${section}:${cue.value}`}
        >
          <span className="section-cue-index" aria-hidden="true">
            {index + 1}
          </span>
          <span className="section-cue-icon" aria-hidden="true">
            <AppIcon name={cue.icon} />
          </span>
          <span className="section-cue-copy">
            <strong>{cue.value}</strong>
            <span>{cue.label}</span>
          </span>
        </li>
      ))}
    </ol>
  );
}

function SectionOverview({ section }: { section: ActiveSection }) {
  const visual = sectionVisual(section);
  return (
    <section
      className="section-overview"
      aria-label={`${visual.label}: ${visual.hint}`}
      style={sectionThemeStyle(section)}
    >
      <SectionCueMap section={section} />
    </section>
  );
}

