interface BundleStatus {
  operation: "exported" | "imported";
  path: string;
  manifest: BundleManifest;
}

function bundleReminderCount(manifest: BundleManifest) {
  return manifest.credential_reminders?.length ?? 0;
}

function bundleStatusTone(status: BundleStatus): ContextReviewCard["tone"] {
  return bundleReminderCount(status.manifest) > 0 ? "warning" : "ok";
}

function bundleTimestampLabel(manifest: BundleManifest) {
  const date = new Date(manifest.exported_at);
  if (Number.isNaN(date.getTime())) {
    return "unknown";
  }
  return date.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
  });
}

function adapterDoctorTone(report: AdapterDoctorReport): ContextReviewCard["tone"] {
  if (report.status === "error" || report.high_risk_finding_count > 0) {
    return "danger";
  }
  if (
    report.status === "warning" ||
    report.quarantined_package_count > 0 ||
    report.unsupported_capability_count > 0 ||
    report.metadata_only_capability_count > 0 ||
    report.secret_requirement_count > 0
  ) {
    return "warning";
  }
  return "ok";
}

function adapterDoctorReadinessTone(
  report: AdapterDoctorReport,
): ContextReviewCard["tone"] {
  if (report.executable_capability_count === 0) {
    return report.capability_count > 0 ? "warning" : "neutral";
  }
  return report.ready_capability_count >= report.executable_capability_count
    ? "ok"
    : "warning";
}

function modelDoctorTone(report: ModelDoctorReport): ContextReviewCard["tone"] {
  if (report.status === "error" || report.errors.length > 0) {
    return "danger";
  }
  if (report.status === "warning" || report.warnings.length > 0) {
    return "warning";
  }
  return "ok";
}

function modelDoctorUnknownProviderCount(report: ModelDoctorReport) {
  return report.saved_models.filter((model) => !model.provider_known).length;
}

function modelDoctorMissingMetadataCount(report: ModelDoctorReport) {
  return report.saved_models.filter((model) => !model.metadata_present).length;
}

function secretRecordFromResult(value: JsonValue): SecretRecord | null {
  if (!isJsonRecord(value) || !isJsonRecord(value.record)) {
    return null;
  }
  const record = value.record;
  const id = scalarText(record.id);
  const backend = scalarText(record.backend);
  const fingerprint = scalarText(record.value_fingerprint);
  const created = scalarText(record.created_at);
  const updated = scalarText(record.updated_at);
  const version =
    typeof record.current_version === "number" ? record.current_version : null;
  if (!id || !backend || !fingerprint || !created || !updated || version === null) {
    return null;
  }
  return {
    id,
    label: scalarText(record.label),
    current_version: version,
    created_at: created,
    updated_at: updated,
    backend,
    value_fingerprint: fingerprint,
  };
}

function secretDeletedState(value: JsonValue) {
  if (!isJsonRecord(value) || typeof value.deleted !== "boolean") {
    return null;
  }
  return {
    id: scalarText(value.id) ?? "unknown",
    deleted: value.deleted,
  };
}

function secretResultTone(value: JsonValue): ContextReviewCard["tone"] {
  const deleted = secretDeletedState(value);
  if (deleted) {
    return deleted.deleted ? "warning" : "danger";
  }
  return secretRecordFromResult(value) ? "ok" : "neutral";
}

function secretResultOperation(value: JsonValue) {
  const deleted = secretDeletedState(value);
  if (deleted) {
    return deleted.deleted ? "deleted" : "missing";
  }
  const record = secretRecordFromResult(value);
  if (record) {
    return record.current_version > 1 ? "rotated" : "stored";
  }
  return "redacted";
}

function secretFingerprintLabel(record: SecretRecord | null) {
  if (!record) return "redacted";
  return record.value_fingerprint.slice(0, 12);
}

function BundleStatusCard({
  status,
  section,
}: {
  status: BundleStatus;
  section: ActiveSection;
}) {
  const reminders = status.manifest.credential_reminders ?? [];
  const reminderCount = bundleReminderCount(status.manifest);
  const visible = reminders.slice(0, 3);
  const tone = bundleStatusTone(status);
  return (
    <div
      className={`bundle-visual-card ${tone}`}
      style={sectionThemeStyle(section)}
    >
      <div className="bundle-visual-head with-icon">
        <span className={`bundle-visual-icon ${tone}`} aria-hidden="true">
          <AppIcon name="artifact" />
        </span>
        <div className="bundle-visual-title">
          <strong>Bundle {status.operation}</strong>
          <span>{status.manifest.profile}</span>
        </div>
      </div>
      <div className="bundle-visual-metrics">
        <VisualMetric
          icon="artifact"
          label="operation"
          value={status.operation}
          section={section}
          tone="ok"
        />
        <VisualMetric
          icon="context"
          label="schema"
          value={status.manifest.schema_version}
          section={section}
        />
        <VisualMetric
          icon="approval"
          label="credentials"
          value={reminderCount}
          section={section}
          tone={reminderCount ? "warning" : "ok"}
        />
        <VisualMetric
          icon="trace"
          label="exported"
          value={bundleTimestampLabel(status.manifest)}
          section={section}
        />
      </div>
      <div className="bundle-visual-detail-list">
        <div className="bundle-visual-detail-row ok">
          <span className="bundle-visual-detail-icon ok" aria-hidden="true">
            <AppIcon name="artifact" />
          </span>
          <div className="bundle-visual-detail-copy">
            <strong>Bundle path</strong>
            <span title={status.path}>{status.path}</span>
          </div>
        </div>
        <div className="bundle-visual-detail-row">
          <span className="bundle-visual-detail-icon" aria-hidden="true">
            <AppIcon name="trace" />
          </span>
          <div className="bundle-visual-detail-copy">
            <strong>Exported at</strong>
            <span>{status.manifest.exported_at}</span>
          </div>
        </div>
        <div
          className={`bundle-visual-detail-row ${
            reminderCount ? "warning" : "ok"
          }`}
        >
          <span
            className={`bundle-visual-detail-icon ${
              reminderCount ? "warning" : "ok"
            }`}
            aria-hidden="true"
          >
            <AppIcon name="approval" />
          </span>
          <div className="bundle-visual-detail-copy">
            <strong>Credential reminders</strong>
            <span>
              {reminderCount
                ? `${reminderCount} credential file(s) omitted`
                : "none"}
            </span>
          </div>
        </div>
        {visible.map((reminder) => (
          <div
            className="bundle-visual-detail-row warning"
            key={reminder.path}
            title={reminder.reason}
          >
            <span
              className="bundle-visual-detail-icon warning"
              aria-hidden="true"
            >
              <AppIcon name="approval" />
            </span>
            <div className="bundle-visual-detail-copy">
              <strong>Omitted credential</strong>
              <span>{reminder.path}</span>
              <span className="bundle-visual-detail-note">{reminder.reason}</span>
            </div>
          </div>
        ))}
        {reminders.length > visible.length ? (
          <div className="bundle-visual-detail-row warning">
            <span
              className="bundle-visual-detail-icon warning"
              aria-hidden="true"
            >
              <AppIcon name="approval" />
            </span>
            <div className="bundle-visual-detail-copy">
              <strong>More reminders</strong>
              <span>
                +{reminders.length - visible.length} credential reminder(s)
              </span>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

function SecretResultCard({ status }: { status: JsonValue }) {
  const record = secretRecordFromResult(status);
  const deleted = secretDeletedState(status);
  const tone = secretResultTone(status);
  const title = record?.label || record?.id || deleted?.id || "Secret result";
  return (
    <div className={`secret-result-card ${tone}`} style={sectionThemeStyle("profiles")}>
      <div className="secret-result-head with-icon">
        <span className={`secret-result-icon ${tone}`} aria-hidden="true">
          <AppIcon name="approval" />
        </span>
        <div className="secret-result-title">
          <strong>{title}</strong>
          <span>secret result / redacted</span>
        </div>
      </div>
      <div className="secret-result-metrics">
        <VisualMetric
          icon="approval"
          label="operation"
          value={secretResultOperation(status)}
          section="profiles"
          tone={tone}
        />
        <VisualMetric
          icon="profile"
          label="backend"
          value={record?.backend ?? "metadata"}
          section="profiles"
          tone={record ? "ok" : "neutral"}
        />
        <VisualMetric
          icon="control"
          label="version"
          value={record?.current_version ?? (deleted?.deleted ? "removed" : "n/a")}
          section="profiles"
          tone={record ? "ok" : deleted?.deleted ? "warning" : "neutral"}
        />
        <VisualMetric
          icon="trace"
          label="fingerprint"
          value={secretFingerprintLabel(record)}
          section="profiles"
          tone={record ? "ok" : "neutral"}
        />
      </div>
      {record ? (
        <div className="secret-result-detail-list">
          <div className="secret-result-detail-row ok">
            <span className="secret-result-detail-icon ok" aria-hidden="true">
              <AppIcon name="profile" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Secret id</strong>
              <span>{record.id}</span>
            </div>
          </div>
          <div className="secret-result-detail-row ok">
            <span className="secret-result-detail-icon ok" aria-hidden="true">
              <AppIcon name="approval" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Value fingerprint</strong>
              <span title={record.value_fingerprint}>
                {record.value_fingerprint}
              </span>
            </div>
          </div>
          <div className="secret-result-detail-row ok">
            <span className="secret-result-detail-icon ok" aria-hidden="true">
              <AppIcon name="trace" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Updated at</strong>
              <span>{record.updated_at}</span>
            </div>
          </div>
          <div className="secret-result-detail-row warning">
            <span
              className="secret-result-detail-icon warning"
              aria-hidden="true"
            >
              <AppIcon name="control" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Secret value</strong>
              <span>withheld</span>
              <span className="secret-result-detail-note">
                Secret values stay redacted on this app surface.
              </span>
            </div>
          </div>
        </div>
      ) : deleted ? (
        <div className="secret-result-detail-list">
          <div
            className={`secret-result-detail-row ${
              deleted.deleted ? "warning" : "danger"
            }`}
          >
            <span
              className={`secret-result-detail-icon ${
                deleted.deleted ? "warning" : "danger"
              }`}
              aria-hidden="true"
            >
              <AppIcon name="profile" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Secret id</strong>
              <span>{deleted.id}</span>
            </div>
          </div>
          <div
            className={`secret-result-detail-row ${
              deleted.deleted ? "warning" : "danger"
            }`}
          >
            <span
              className={`secret-result-detail-icon ${
                deleted.deleted ? "warning" : "danger"
              }`}
              aria-hidden="true"
            >
              <AppIcon name="approval" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Metadata state</strong>
              <span>
                {deleted.deleted ? "removed from metadata" : "was not removed"}
              </span>
            </div>
          </div>
        </div>
      ) : (
        <div className="secret-result-detail-list">
          <div className="secret-result-detail-row warning">
            <span
              className="secret-result-detail-icon warning"
              aria-hidden="true"
            >
              <AppIcon name="control" />
            </span>
            <div className="secret-result-detail-copy">
              <strong>Secret values</strong>
              <span>not returned</span>
              <span className="secret-result-detail-note">
                This app surface keeps secret values redacted.
              </span>
            </div>
          </div>
        </div>
      )}
      <pre>{JSON.stringify(status, null, 2)}</pre>
    </div>
  );
}

