  async function showAgentFromOps() {
    const id = requireOpsId("Agent show");
    if (!id) return;
    await showAgent(id);
  }

  async function useAgentFromOps() {
    const id = requireOpsId("Agent use");
    if (!id) return;
    await useAgent(id);
  }

  async function useAgent(id: string) {
    const existing = agentConfigs.find(
      (doc): doc is AgentConfigFile =>
        doc.id === id && "system_prompt" in doc,
    );
    if (existing) {
      applyAgentConfigToControls(existing);
      return;
    }
    await showAgent(id, { applyToControls: true });
  }

  async function showAgent(
    id: string,
    options: { applyToControls?: boolean } = {},
  ) {
    try {
      const doc =
        transport === "daemon"
          ? await daemonJson<AgentConfigFile>(`/agents/${encodeURIComponent(id)}`)
          : await invoke<AgentConfigFile>("agent_show", { id });
      setAgentConfigs((docs) =>
        upsertAgentConfig(docs, withExistingAgentMetadata(docs, doc)),
      );
      if (options.applyToControls) {
        applyAgentConfigToControls(doc);
      }
      appendJson("Agent", doc);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      appendLine("error", `Agent show failed: ${msg}`);
    }
  }

  function applyAgentConfigToControls(doc: AgentConfigFile) {
    const refinement = doc.prompt_refinement ?? null;
    const refinementRules = doc.prompt_refinements ?? [];
    setAgentId(doc.id);
    setOpsId(doc.id);
    setOpsValue(doc.system_prompt);
    setModel(doc.model ?? "");
    setVoiceInputEnabled(triStateBoolValue(doc.voice?.input_enabled));
    setVoiceOutputEnabled(triStateBoolValue(doc.voice?.output_enabled));
    setVoiceInputBackend(doc.voice?.input_backend ?? "");
    setVoiceInputProvider(doc.voice?.input_provider ?? "");
    setVoiceInputModel(doc.voice?.input_model ?? "");
    setVoiceOutputBackend(doc.voice?.output_backend ?? "");
    setVoiceTtsProvider(doc.voice?.tts_provider ?? "");
    setVoiceTtsModel(doc.voice?.tts_model ?? "");
    setVoiceName(doc.voice?.voice ?? "");
    setVoiceTone(doc.voice?.tone ?? "");
    setToolOverridesJson(jsonArrayControlValue(doc.tool_overrides));
    setSkillOverridesJson(jsonArrayControlValue(doc.skill_overrides));
    setInputCostPerMillion(numberControlValue(doc.input_cost_per_million));
    setOutputCostPerMillion(numberControlValue(doc.output_cost_per_million));
    setMaxToolCalls(numberControlValue(doc.max_tool_calls));
    setMaxTokensBeforeCompaction(
      numberControlValue(doc.max_tokens_before_compaction),
    );
    setMaxCompactionOutputTokens(
      numberControlValue(doc.max_compaction_output_tokens),
    );
    setCompactionGuidance(doc.compaction_guidance ?? "");
    setMaxSubagentDepth(numberControlValue(doc.max_subagent_depth));
    setMaxRecursionDepth(numberControlValue(doc.max_recursion_depth));
    setStopRetentionMode(doc.stop_retention_mode ?? null);
    setEnableCapabilityDrafts(doc.capability_drafts_enabled === true);
    setCapabilityDraftGuidance(doc.capability_draft_guidance ?? "");
    setDisabledLifecycleHooks((doc.disabled_lifecycle_hooks ?? []).join(", "));
    setRawToolOutput(doc.tool_output_mode === "raw");
    setToolRoutingModel(doc.tool_routing_model ?? "");
    setToolOutputInterpretationModel(
      doc.tool_output_interpretation_model ?? "",
    );
    setToolVisibility(doc.tool_visibility ?? "");
    setSkillVisibility(doc.skill_visibility ?? "");
    setLoadMemory(doc.load_memory === true);
    setMemoryBackend(doc.memory_backend ?? "");
    setMemoryModel(doc.memory_model ?? "");
    setLoadSkills(doc.load_skills === true);
    setIngestionGuardrailMode(doc.ingestion_guardrail ?? "");
    setAllowUnsafeIngest(doc.ingestion_guardrail === "allow");
    setIngestGuardrailModel(doc.ingestion_guardrail_model ?? "");
    setAllowedTools((doc.allowed_tools ?? []).join(", "));
    setAllowedToolCategories((doc.allowed_tool_categories ?? []).join(", "));
    setAllowedSkillCategories((doc.allowed_skill_categories ?? []).join(", "));
    setRunApprovalControllerAgent(doc.approval_controller_agent ?? "");
    setApprovalControllerTools(
      (doc.approval_controller_allowed_tools ?? []).join(", "),
    );
    setApprovalControllerCategories(
      (doc.approval_controller_allowed_tool_categories ?? []).join(", "),
    );
    setEnablePromptRefinement(refinement != null || refinementRules.length > 0);
    setPromptRefinementInstructions(refinement?.instructions ?? "");
    setPromptRefinementModel(refinement?.model ?? "");
    setPromptRefinementAgentAwareness(refinement?.agent_awareness === true);
    setPromptRefinementsJson(jsonArrayControlValue(refinementRules));
    appendEvent(`Applied saved agent ${doc.id} to run controls.`);
  }

  function numberControlValue(value: number | null | undefined) {
    return value == null ? "" : String(value);
  }

  function triStateBoolValue(value: boolean | null | undefined) {
    return value == null ? "" : value ? "on" : "off";
  }

  function optionalTriStateBool(value: "" | "on" | "off") {
    return value === "" ? null : value === "on";
  }

  function voiceConfigFromCurrentControls(): AgentConfigFile["voice"] {
    const voice = {
      input_enabled: optionalTriStateBool(voiceInputEnabled),
      output_enabled: optionalTriStateBool(voiceOutputEnabled),
      input_backend: voiceInputBackend.trim() || null,
      input_provider: voiceInputProvider.trim() || null,
      input_model: voiceInputModel.trim() || null,
      output_backend: voiceOutputBackend.trim() || null,
      tts_provider: voiceTtsProvider.trim() || null,
      tts_model: voiceTtsModel.trim() || null,
      voice: voiceName.trim() || null,
      tone: voiceTone.trim() || null,
    };
    return Object.values(voice).some((value) => value !== null) ? voice : null;
  }

  function jsonArrayControlValue(items: unknown[] | null | undefined) {
    return items?.length ? JSON.stringify(items, null, 2) : "";
  }

  function parseJsonArrayControl<T>(value: string, label: string): T[] {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (!Array.isArray(parsed)) {
        throw new Error("value must be a JSON array");
      }
      return parsed as T[];
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`${label} must be a JSON array: ${msg}`);
    }
  }

  function agentConfigFromCurrentControls(id: string, systemPrompt: string): AgentConfigFile {
    const promptRefinements = enablePromptRefinement
      ? parseJsonArrayControl<AgentPromptRefinementConfig>(
          promptRefinementsJson,
          "Prompt refinement rules",
        )
      : [];
    return {
      id,
      name: id,
      system_prompt: systemPrompt,
      voice: voiceConfigFromCurrentControls(),
      prompt_refinement:
        enablePromptRefinement && promptRefinementInstructions.trim()
          ? {
              instructions: promptRefinementInstructions.trim(),
              model: promptRefinementModel.trim() || null,
              agent_awareness: promptRefinementAgentAwareness,
            }
          : null,
      prompt_refinements:
        enablePromptRefinement && promptRefinements.length
          ? promptRefinements
          : undefined,
      tool_overrides: parseJsonArrayControl(
        toolOverridesJson,
        "Tool overrides",
      ),
      skill_overrides: parseJsonArrayControl(
        skillOverridesJson,
        "Skill overrides",
      ),
      model: model.trim() || null,
      input_cost_per_million: parseOptionalNonNegativeFloat(inputCostPerMillion),
      output_cost_per_million: parseOptionalNonNegativeFloat(
        outputCostPerMillion,
      ),
      max_tool_calls: parseOptionalNonNegativeInt(maxToolCalls),
      max_tokens_before_compaction: parseOptionalPositiveInt(
        maxTokensBeforeCompaction,
      ),
      max_compaction_output_tokens: parseOptionalPositiveInt(
        maxCompactionOutputTokens,
      ),
      compaction_guidance: compactionGuidance.trim() || null,
      max_subagent_depth: parseOptionalNonNegativeInt(maxSubagentDepth),
      max_recursion_depth: parseOptionalNonNegativeInt(maxRecursionDepth),
      stop_retention_mode: stopRetentionMode,
      capability_drafts_enabled: enableCapabilityDrafts || null,
      capability_draft_guidance: capabilityDraftGuidance.trim() || null,
      disabled_lifecycle_hooks: optionalList(
        parsedCategoryList(disabledLifecycleHooks),
      ),
      tool_output_mode: rawToolOutput ? "raw" : "interpreted",
      tool_routing_model: toolRoutingModel.trim() || null,
      tool_output_interpretation_model:
        toolOutputInterpretationModel.trim() || null,
      tool_visibility: toolVisibility || null,
      skill_visibility: skillVisibility || null,
      load_memory: loadMemory || null,
      memory_backend: memoryBackend.trim() || null,
      memory_model: memoryModel.trim() || null,
      load_skills: loadSkills || null,
      ingestion_guardrail: runIngestionGuardrailMode(),
      ingestion_guardrail_model: ingestGuardrailModel.trim() || null,
      allowed_tools: optionalList(parsedCategoryList(allowedTools)),
      allowed_tool_categories: optionalList(
        parsedCategoryList(allowedToolCategories),
      ),
      allowed_skill_categories: optionalList(
        parsedCategoryList(allowedSkillCategories),
      ),
      approval_controller_agent: runApprovalControllerAgent.trim() || null,
      approval_controller_allowed_tools: optionalList(
        parsedCategoryList(approvalControllerTools),
      ),
      approval_controller_allowed_tool_categories: optionalList(
        parsedCategoryList(approvalControllerCategories),
      ),
    };
  }

  async function saveAgentFromOps() {
    const id = requireOpsId("Agent save");
    const systemPrompt = requireOpsValue("Agent save system prompt");
    if (!id || !systemPrompt) return;
    await saveAgent(id, systemPrompt);
  }

  async function saveAgent(id: string, systemPrompt: string) {
    let doc: AgentConfigFile;
    try {
      doc = agentConfigFromCurrentControls(id, systemPrompt);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      appendLine("error", `Agent save failed: ${msg}`);
      return;
    }
    if (
      enablePromptRefinement &&
      !doc.prompt_refinement &&
      !doc.prompt_refinements?.length
    ) {
      appendLine(
        "error",
        "Agent save needs refinement instructions or refinement rules when prompt refinement is enabled.",
      );
      return;
    }
    try {
      const saved =
        transport === "daemon"
          ? await daemonJson<AgentConfigFile>("/agents", doc)
          : await invoke<AgentConfigFile>("agent_save", { agent: doc });
      setAgentConfigs((docs) => upsertAgentConfig(docs, saved));
      setAgentId(saved.id);
      appendJson("Agent saved", saved);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      appendLine("error", `Agent save failed: ${msg}`);
    }
  }

