      const doc =
        transport === "daemon"
          ? await daemonJson<AgentConfigFile>("/agents/import", { path })
          : await invoke<AgentConfigFile>("agent_import", { path });
      setAgentConfigs((docs) => upsertAgentConfig(docs, doc));
      setAgentId(doc.id);
