      setProfileGrants((grants) =>
        grants.filter((grant) => grant.from_profile !== id && grant.to_profile !== id),
      );
      if (currentProfile?.id === id) {
        setCurrentProfile(null);
      }
      appendJson("Profile deleted", result);
