  function applyModelConfigToControls(doc: SavedModelConfig) {
    const providerId = doc.provider?.trim() || provider;
    const metadata = doc.metadata ?? {};
    const providerOptions = metadata.provider_options;
    const optionRecord = providerOptions && isJsonRecord(providerOptions)
      ? providerOptions
      : {};
    setOpsId(doc.id);
    setModel(doc.id);
    if (doc.provider?.trim()) {
      setProvider(doc.provider.trim());
    }
    setApiBaseUrl(doc.api_base_url ?? "");
    setApiKeyEnv(doc.api_key_env ?? defaultApiKeyEnvForProvider(providerId));
    setModelMaxContextTokens(numberControlValue(doc.max_context_tokens));
    setRunMaxOutputTokens(numberControlValue(doc.max_output_tokens));
    setRunTemperature(numberControlValue(doc.default_temperature));
    setModelSupportsImage((doc.available_modalities ?? []).includes("image"));
    setModelModalities((doc.available_modalities ?? []).join(", "));
    setModelReasoningMode(doc.reasoning_mode ?? "");
    setModelToolSupport(
      doc.tool_support == null ? "" : doc.tool_support ? "true" : "false",
    );
    setModelPrivacyLevel(doc.privacy_level ?? "");
    setModelCostTier(doc.cost_tier ?? "");
    setModelMetadataJson(modelMetadataControlValue(metadata));
    setInputCostPerMillion(numberControlValue(doc.input_cost_per_million));
    setOutputCostPerMillion(numberControlValue(doc.output_cost_per_million));
    setProviderTopP(modelProviderOptionControlValue(optionRecord.top_p));
    setProviderTopK(modelProviderOptionControlValue(optionRecord.top_k));
    setProviderReasoningEffort(
      modelProviderOptionControlValue(optionRecord.reasoning_effort),
    );
    setProviderFrequencyPenalty(
      modelProviderOptionControlValue(optionRecord.frequency_penalty),
    );
    setProviderPresencePenalty(
      modelProviderOptionControlValue(optionRecord.presence_penalty),
    );
    appendEvent(`Loaded saved model ${doc.id} into model controls.`);
  }

  function applyProviderDescriptorToControls(descriptor: ModelProviderDescriptor) {
    setProvider(descriptor.id);
    setModel(descriptor.default_model);
    setApiBaseUrl(descriptor.api_base_url ?? "");
    setApiKeyEnv(descriptor.api_key_env ?? defaultApiKeyEnvForProvider(descriptor.id));
    setModelSupportsImage(descriptor.available_modalities.includes("image"));
    setModelModalities(descriptor.available_modalities.join(", "));
    setModelToolSupport(
      descriptor.tool_support == null
        ? ""
        : descriptor.tool_support
          ? "true"
          : "false",
    );
    setProviderTopP("");
    setProviderTopK("");
    setProviderReasoningEffort("");
    setProviderFrequencyPenalty("");
    setProviderPresencePenalty("");
    appendEvent(`Applied provider ${descriptor.id} defaults to model controls.`);
  }

  function modelProviderOptionControlValue(value: JsonValue | undefined) {
    if (typeof value === "string") {
      return value;
    }
    if (typeof value === "number" && Number.isFinite(value)) {
      return String(value);
    }
    if (typeof value === "boolean") {
      return String(value);
    }
    return "";
  }

  function modelMetadataControlValue(metadata: { [key: string]: JsonValue }) {
    return Object.keys(metadata).length ? JSON.stringify(metadata, null, 2) : "";
  }

  function savedModelMetadataKeys(doc: SavedModelConfig) {
    return Object.keys(doc.metadata ?? {})
      .filter((key) => key !== "provider_options")
      .sort();
  }

  function savedModelProviderOptionKeys(doc: SavedModelConfig) {
    const options = doc.metadata?.provider_options;
    return options && isJsonRecord(options) ? Object.keys(options).sort() : [];
  }

  function currentModelModalities() {
    const modalities = parsedCategoryList(modelModalities);
    if (modalities.length) {
      return modalities;
    }
    return modelSupportsImage ? ["text", "image"] : [];
  }

  function toggleImageModality(checked: boolean) {
    setModelSupportsImage(checked);
    setModelModalities((current) => {
      const modalities = parsedCategoryList(current);
      if (!modalities.length) {
        return checked ? "text, image" : "";
      }
      const withoutImage = modalities.filter((item) => item !== "image");
      if (!checked) {
        return withoutImage.join(", ");
      }
      const next = withoutImage.includes("text")
        ? [...withoutImage, "image"]
        : ["text", ...withoutImage, "image"];
      return next.join(", ");
    });
  }

