  async function saveCurrentModelFromControls() {
    if (provider === "fake") {
      appendLine("error", "Choose a non-fake provider before saving model metadata.");
      return;
    }
    const id = model.trim() || defaultModelForProvider(provider);
    const providerOptions = providerOptionsFromControls();
    if (providerOptions === false) return;
    const metadata = modelMetadataFromControls(providerOptions);
    if (!metadata) return;
    const modelDoc = {
      id,
      provider,
      api_base_url: supportsApiBaseUrl ? apiBaseUrl.trim() || null : null,
      api_key_env: apiKeyEnv.trim() || defaultApiKeyEnvForProvider(provider),
      allow_missing_api_key: providerAllowsMissingApiKey(provider) ? true : null,
      max_context_tokens: parseOptionalPositiveInt(modelMaxContextTokens),
      max_output_tokens: supportsMaxOutputTokens
        ? parseOptionalPositiveInt(runMaxOutputTokens)
        : null,
      default_temperature: supportsTemperature
        ? parseOptionalNonNegativeFloat(runTemperature)
        : null,
      available_modalities: currentModelModalities(),
      reasoning_mode: modelReasoningMode.trim() || null,
      tool_support:
        modelToolSupport === "true"
          ? true
          : modelToolSupport === "false"
            ? false
            : null,
      privacy_level: modelPrivacyLevel.trim() || null,
      cost_tier: modelCostTier.trim() || null,
      input_cost_per_million: parseOptionalNonNegativeFloat(inputCostPerMillion),
      output_cost_per_million: parseOptionalNonNegativeFloat(outputCostPerMillion),
      metadata,
    };
    try {
      const doc =
        transport === "daemon"
          ? await daemonJson<SavedModelConfig>("/models", modelDoc)
          : await invoke<SavedModelConfig>("model_save", { model: modelDoc });
      setModelConfigs((docs) => upsertSavedModelConfig(docs, doc));
      appendJson("Model saved", doc);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      appendLine("error", `Model save failed: ${msg}`);
    }
  }

