  function providerOptionsFromControls(): Record<string, unknown> | false | null {
    const options: Record<string, unknown> = {};
    const controlValues: Record<(typeof MODEL_PROVIDER_OPTION_KEYS)[number], string> = {
      top_p: providerTopP,
      top_k: providerTopK,
      reasoning_effort: providerReasoningEffort,
      frequency_penalty: providerFrequencyPenalty,
      presence_penalty: providerPresencePenalty,
    };
    for (const key of MODEL_PROVIDER_OPTION_KEYS) {
      if (!addProviderOption(options, key, controlValues[key])) {
        return false;
      }
    }
    return Object.keys(options).length ? options : null;
  }

  function modelMetadataFromControls(providerOptions: Record<string, unknown> | null) {
    const parsed = parseJsonObject("Model metadata", modelMetadataJson.trim());
    if (!parsed) return null;
    const metadata = { ...parsed };
    const existingOptions = metadata.provider_options;
    if (existingOptions != null && !isUnknownRecord(existingOptions)) {
      appendLine("error", "Model metadata.provider_options must be a JSON object.");
      return null;
    }
    const mergedOptions: Record<string, unknown> = isUnknownRecord(existingOptions)
      ? { ...existingOptions }
      : {};
    for (const key of MODEL_PROVIDER_OPTION_KEYS) {
      delete mergedOptions[key];
    }
    if (providerOptions) {
      Object.assign(mergedOptions, providerOptions);
    }
    if (Object.keys(mergedOptions).length) {
      metadata.provider_options = mergedOptions;
    } else {
      delete metadata.provider_options;
    }
    return metadata;
  }

  function addProviderOption(
    options: Record<string, unknown>,
    key: string,
    raw: string,
  ) {
    const trimmed = raw.trim();
    if (!trimmed) {
      return true;
    }
    const descriptor = providerOptionDescriptor(key);
    if (!descriptor && !providerSupportsProviderOption(key)) {
      appendLine("error", `${providerOptionLabel(key)} is not supported by ${provider}.`);
      return false;
    }
    const value = parseProviderOptionValue(key, trimmed, descriptor ?? undefined);
    if (value === false) {
      return false;
    }
    options[key] = value;
    return true;
  }

  function parseProviderOptionValue(
    key: string,
    raw: string,
    descriptor?: ModelProviderOptionDescriptor,
  ): number | string | false {
    const kind = descriptor?.kind ?? fallbackProviderOptionKind(key);
    if (kind === "string") {
      return raw;
    }
    const value = Number(raw);
    if (!Number.isFinite(value)) {
      appendLine("error", `${providerOptionLabel(key)} must be a number.`);
      return false;
    }
    if (kind === "integer" && !Number.isInteger(value)) {
      appendLine("error", `${providerOptionLabel(key)} must be an integer.`);
      return false;
    }
    const min = descriptor?.min ?? fallbackProviderOptionMin(key);
    const max = descriptor?.max ?? fallbackProviderOptionMax(key);
    if (min !== null && value < min) {
      appendLine("error", `${providerOptionLabel(key)} must be at least ${min}.`);
      return false;
    }
    if (max !== null && value > max) {
      appendLine("error", `${providerOptionLabel(key)} must be at most ${max}.`);
      return false;
    }
    return value;
  }

