                                  <VisualMetric
                                    icon="setup"
                                    label="deps"
                                    value={
                                      backend.local_dependencies_ready
                                        ? "ready"
                                        : "missing"
                                    }
                                    section="ingest"
                                    tone={
                                      backend.local_dependencies_ready
                                        ? "ok"
                                        : "warning"
                                    }
                                  />
                                  <VisualMetric
                                    icon="tools"
                                    label="missing"
