                                <div className="tool-detail-row ok">
                                  <span
                                    className="tool-detail-icon ok"
                                    aria-hidden="true"
                                  >
                                    <AppIcon name="trace" />
                                  </span>
                                  <div className="tool-detail-copy">
                                    <strong>Categories</strong>
                                    <span>{tool.categories.join(", ")}</span>
                                  </div>
                                </div>
